pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Set jojoTeam so onlyJojoTeam allows testing
        c = new C();
        vm.store(address(c), bytes32(uint256(0)), bytes32(uint256(uint160(address(this)))));
    }
    function testFuzz_property(address caller, string calldata description) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        // A helper contract that forwards a call to newEmergencyOracle on behalf of the JOJO team
        Forwarder helper = new Forwarder(c);
        vm.prank(helper);
        try c.newEmergencyOracle(description) {
        } catch {
            assertTrue(false, "call should succeed");
        }
        // Parse the emitted event from helper's execution
        vm.recordLogs();
        vm.prank(helper);
        c.newEmergencyOracle(description);
        Vm.Log[] memory entries = vm.getRecordedLogs();
        address emittedOwner = address(0);
        for (uint i = 0; i < entries.length; i++) {
            if (entries[i].topics[0] == keccak256("NewEmergencyOracle(address,address)")) {
                (, emittedOwner, ) = abi.decode(entries[i].data, (address, address));
                break;
            }
        }
        // The emitted owner must equal msg.sender of the direct caller to newEmergencyOracle,
        // which in this setup is the Forwarder contract address.
        assertTrue(emittedOwner == address(helper));
    }
}

contract Forwarder {
    C public target;
    constructor(C _target) { target = _target; }
    fallback() external payable {
        // Forward the call to target's newEmergencyOracle; the msg.sender seen by C will be this Forwarder
        (bool ok, bytes memory ret) = address(target).delegatecall(msg.data);
        if (!ok) {
            assembly { revert(add(ret, 0x20), mload(ret)) }
        }
        assembly { return(add(ret, 0x20), mload(ret)) }
    }
}
